UIExplosionGroup=function(game){Phaser.Group.call(this,game,null);this.emitter=this.add(new UIExplosionEmitter(game));this.exists=false;this.visible=false;};UIExplosionGroup.prototype=Object.create(Phaser.Group.prototype);UIExplosionGroup.prototype.constructor=UIExplosionGroup;UIExplosionGroup.prototype.update=function(){if(!this.exists){return;}Phaser.Group.prototype.update.call(this);if(this.countLiving()==0){this.exists=false;this.visible=false;}};UIExplosionGroup.prototype.postUpdate=function(){if(!this.exists){return;}Phaser.Group.prototype.postUpdate.call(this);};UIExplosionGroup.prototype.spawn=function(x,y,sound,smokeCount){sound.play();this.exists=true;this.visible=true;this.emitter.spawn(x,y,smokeCount);};UIExplosionGroup.prototype.retire=function(){this.exists=false;this.visible=false;this.emitter.retire();};